  private setupKeyboardShortcuts(): void {
    if (!this.isBrowser) return;

    document.addEventListener('keydown', (event) => {
      if ((event.ctrlKey || event.metaKey) && event.key === 'k') {
        event.preventDefault();
        this.onOpenSearchModal();
      }

      if (event.key === 'Escape') {
        if (this.isSearchOpen) this.closeSearchModal();
        if (this.isUserMenuOpen) this.isUserMenuOpen = false;
        if (this.showVisorHelp) this.cerrarAyudaVisor();
      }

      switch(event.key) {
        case 'ArrowLeft':
          event.preventDefault();
          this.paginaAnterior();
          break;
        case 'ArrowRight':
          event.preventDefault();
          this.paginaSiguiente();
          break;
        case '+':
        case '=':
          if (event.ctrlKey) {
            event.preventDefault();
            this.zoomIn();
          }
          break;
        case '-':
          if (event.ctrlKey) {
            event.preventDefault();
            this.zoomOut();
          }
          break;
        case 'b':
        case 'B':
          if (event.ctrlKey) {
            event.preventDefault();
            this.toggleMarcadorPagina();
          }
          break;
        case 'f':
        case 'F':
          event.preventDefault();
          this.togglePantallaCompleta();
          break;
        case 'n':
        case 'N':
          if (event.ctrlKey) {
            event.preventDefault();
            this.toggleNotas();
          }
          break;
        case 'd':
        case 'D':
          if (event.ctrlKey) {
            event.preventDefault();
            this.descargarPDF();
          }
          break;
        case 'p':
        case 'P':
          if (event.ctrlKey) {
            event.preventDefault();
            this.imprimirPaginaActual();
          }
          break;
      }
    });
  }

