// Método para generar PDF demo si no existe
async generarPDFDemo(): Promise<void> {
  try {
    console.log('Generando PDF demo...');

    // Verificar si jsPDF está disponible
    let jsPDFModule;
    try {
      jsPDFModule = await import('jspdf');
    } catch (error) {
      console.warn('jsPDF no disponible, usando PDF base64');
      return this.usarPDFBase64Demo();
    }

    const { jsPDF } = jsPDFModule;
    const doc = new jsPDF();

    // Título
    doc.setFontSize(24);
    doc.setTextColor(79, 70, 229); // Color primario
    doc.text('Manual de Usuario SIGPAZ', 20, 30);

    // Información del sistema
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.text('Versión 2.5.1', 20, 45);
    doc.text('Manual de Demostración', 20, 55);

    // Separador
    doc.setDrawColor(79, 70, 229);
    doc.setLineWidth(1);
    doc.line(20, 60, 190, 60);

    // Contenido
    doc.setFontSize(14);
    doc.text('Bienvenido al Manual de Usuario SIGPAZ', 20, 75);

    doc.setFontSize(11);
    const contenido = [
      'Este es un PDF de demostración generado automáticamente porque',
      'el archivo PDF original no se encontró en el servidor.',
      '',
      'Para solucionar este problema:',
      '1. Coloca el archivo manual-usuario-sigpaz.pdf en la carpeta:',
      '   src/assets/manuales/',
      '2. O contacta al administrador del sistema.',
      '',
      'Características del visor:',
      '• Navegación por páginas',
      '• Zoom in/out',
      '• Marcadores',
      '• Notas por página',
      '• Búsqueda de contenido',
      '• Modo nocturno',
      '',
      `Fecha: ${new Date().toLocaleDateString()}`,
      'Este documento es temporal y será reemplazado cuando',
      'se cargue el PDF oficial del manual.'
    ];

    let y = 85;
    contenido.forEach(linea => {
      if (y > 270) {
        doc.addPage();
        y = 20;
      }
      doc.text(linea, 20, y);
      y += 7;
    });

    // Pie de página
    doc.setFontSize(10);
    doc.setTextColor(100, 100, 100);
    doc.text('SIGPAZ - Sistema Integrado de Gestión para la Paz', 105, 285, { align: 'center' });

    // Guardar como blob
    const pdfBlob = doc.output('blob');
    const url = URL.createObjectURL(pdfBlob);

    // Actualizar la fuente del PDF
    this.pdfSrc = url;
    this.pdfDemoSrc = url;

    this.notificationService.addNotification({
      userId: 'Sistema',
      title: 'PDF demo generado',
      message: 'PDF demo generado',
      metadata: { avatar: '✅' },
      module: 'manual-tecnico',
      type: 'success'
    });
    // Cargar el PDF generado
    setTimeout(() => {
      this.cargarPDF();
    }, 500);

  } catch (error) {
    console.error('Error generando PDF demo:', error);
    // Último recurso: usar PDF base64
    this.usarPDFBase64Demo();
  }
}
