crearPDFDemoSimple(): void {
  // Crear un canvas con contenido simulado
  const canvas = this.pdfCanvas?.nativeElement;
  if (!canvas) return;

  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  // Configurar canvas
  canvas.width = 800;
  canvas.height = 1131; // Tamaño A4

  // Fondo blanco
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Título
  ctx.fillStyle = '#4f46e5';
  ctx.font = 'bold 32px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('📘 Manual de Usuario SIGPAZ', canvas.width / 2, 100);

  // Subtítulo
  ctx.fillStyle = '#6b7280';
  ctx.font = '20px Arial';
  ctx.fillText('Versión 2.5.1 - Modo Demostración', canvas.width / 2, 140);

  // Línea separadora
  ctx.strokeStyle = '#4f46e5';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(100, 180);
  ctx.lineTo(canvas.width - 100, 180);
  ctx.stroke();

  // Contenido
  ctx.fillStyle = '#1f2937';
  ctx.font = '18px Arial';
  ctx.textAlign = 'left';

  const contenido = [
    `Página ${this.currentPage} de ${this.totalPaginas}`,
    '',
    'Este es un contenido de demostración porque',
    'el archivo PDF original no se encuentra.',
    '',
    'Para solucionar este problema:',
    '1. Coloca el archivo manual-usuario-sigpaz.pdf',
    '   en la carpeta: src/assets/manuales/',
    '2. O contacta al administrador del sistema.',
    '',
    'Características disponibles:',
    '• Navegación por páginas',
    '• Zoom in/out',
    '• Marcadores',
    '• Notas por página',
    '• Búsqueda de contenido',
    '',
    `Fecha: ${new Date().toLocaleDateString()}`,
    'Hora: ' + new Date().toLocaleTimeString()
  ];

  let y = 220;
  contenido.forEach(linea => {
    ctx.fillText(linea, 100, y);
    y += 30;
  });

  // Pie de página
  ctx.fillStyle = '#9ca3af';
  ctx.font = '14px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('SIGPAZ - Sistema Integrado de Gestión para la Paz', canvas.width / 2, canvas.height - 50);

  // Marcar como cargado
  this.pdfLoaded = true;
  this.pdfLoadProgress = 100;
}

